function useKeyboardSheet(open:boolean,onOpenChange:(open:boolean)=>void){
 const keyboard=useKeyboard();
 const keyboardInteraction=useRef(false);
 useEffect(()=>{
  if(!open)return;
  // The phone keyboard is a sibling of the sheet portal. Its keys belong to this input session.
  const trackInteraction=(event:Event)=>{keyboardInteraction.current=event.type==='pointerdown'&&event.target instanceof Element&&!!event.target.closest('.keyboard-dock');};
  document.addEventListener('pointerdown',trackInteraction,true);
  document.addEventListener('keydown',trackInteraction,true);
  return()=>{document.removeEventListener('pointerdown',trackInteraction,true);document.removeEventListener('keydown',trackInteraction,true);keyboardInteraction.current=false;};
 },[open]);
 return (next:boolean)=>{if(!next&&keyboardInteraction.current)return;if(!next)keyboard.hide();onOpenChange(next);};
}
