function IntakeChart(){const{logs}=useStore();const canvas=useRef<HTMLCanvasElement>(null);useEffect(()=>{if(!canvas.current)return;const values=[...logs].reverse().map(ounces);const peak=Math.max(...values);const max=Math.max(160,Math.ceil((peak+Math.max(8,peak*.05))/40)*40);const step=max/4;const c=new Chart(canvas.current,{type:'line',data:{labels:chartDates.map((d,i)=>chartCrossesMonth&&(i===0||d.getDate()===1)?d.toLocaleDateString('en-US',{month:'short',day:'numeric'}):String(d.getDate())),datasets:[{data:values,clip:false,borderColor:'#e1e6e4',borderWidth:1.2,pointRadius:4,pointHoverRadius:6,pointBackgroundColor:'#fff',pointBorderColor:'#106b70',pointBorderWidth:1.3,tension:0}]},options:{responsive:true,maintainAspectRatio:false,animation:{duration:220},plugins:{legend:{display:false},tooltip:{displayColors:false,backgroundColor:'#106b70',callbacks:{label:c=>`${c.parsed.y} oz`}}},scales:{x:{grid:{display:false},border:{color:'#e0e5e3'},ticks:{color:'#535b5a',font:{family:'Work Sans',size:11},padding:12}},y:{min:0,max,grid:{color:'#eaebeb',drawTicks:false},border:{display:false,dash:[4,4]},ticks:{stepSize:step,color:'#6e7776',font:{family:'Work Sans',size:10},padding:9,callback:v=>String(Number(v))}}},layout:{padding:{top:12,right:12,bottom:8,left:6}}}});return()=>c.destroy();},[logs]);return <section className="intake-chart" aria-label="Fluid intake in ounces over the past seven days"><div className="chart-wrap"><canvas ref={canvas} role="img" aria-label={'Seven-day fluid intake: '+[...logs].reverse().map(ounces).join(', ')+' ounces'}/></div><span className="chart-month">{chartCrossesMonth?'':dateAt().toLocaleDateString('en-US',{month:'short'})}</span></section>;}
