function nextReminderLabel(r:Reminder){
 const now=new Date(), base=new Date(today+'T00:00:00');
 for(let offset=0;offset<370;offset++){
  const date=new Date(base);date.setDate(date.getDate()+offset);
  const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
  if(key<r.start||(!r.never&&key>r.end))continue;
  if(r.repeat==='selected'&&!r.days.includes((date.getDay()+6)%7))continue;
  const time=[...r.times].sort().find(t=>offset>0||t>`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`);
  if(time)return timeLabel(time);
 }
 return 'Schedule ended';
}
