function Calendar({value,min,onSelect}:{value:string;min?:string;onSelect:(d:string)=>void}){const[month,setMonth]=useState(new Date(value+'T12:00:00'));const year=month.getFullYear(),m=month.getMonth(),days=new Date(year,m+1,0).getDate(),offset=(new Date(year,m,1).getDay()+6)%7;return <div className="calendar-picker"><div className="calendar-heading"><button className="icon-button" aria-label="Previous month" onClick={()=>setMonth(new Date(year,m-1,1))}><Icon name="back"/></button><strong>{month.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</strong><button className="icon-button flip" aria-label="Next month" onClick={()=>setMonth(new Date(year,m+1,1))}><Icon name="back"/></button></div><div className="calendar-grid">{weekdays.map(d=><small key={d}>{d.slice(0,1)}</small>)}{Array.from({length:offset},(_,i)=><span key={'blank'+i}/>)}{Array.from({length:days},(_,i)=>{const date=`${year}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return <button key={date} disabled={!!min&&date<min} className={date===value?'selected':''} aria-label={date} aria-pressed={date===value} onClick={()=>onSelect(date)}>{i+1}</button>;})}</div></div>;}
function Setup(){const store=useStore();const{draft:r,setDraft}=store;const[advanced,setAdvanced]=useState(false),[timeEdit,setTimeEdit]=useState<number|null>(null),[dateEdit,setDateEdit]=useState<'start'|'end'|null>(null),[timeError,setTimeError]=useState('');const keyboard=useKeyboard();const patch=(p:Partial<Reminder>)=>setDraft(v=>({...v,...p}));const adding=timeEdit===-1;
 return <><MobileScroll className="setup-scroll"><main className="setup-content"><section><h2>Reminder Time</h2><div className="time-grid">{r.times.map((t,i)=><div className="time-chip" key={t}><button className="time-edit" aria-label={'Edit time '+timeLabel(t)} onClick={()=>{setTimeError('');setTimeEdit(i);}}><Icon name="clock" size={16}/><span>{timeLabel(t,false)}</span></button><button className="time-remove" aria-label={'Remove time '+timeLabel(t)} onClick={()=>patch({times:r.times.filter((_,j)=>j!==i)})}><Icon name="close" size={14}/></button></div>)}<button className="outline-button add-time" onClick={()=>{setTimeError('');setTimeEdit(-1);}}>Add Time <Icon name="add" size={20}/></button></div>{r.times.length===0&&<p className="field-error">Add at least one reminder time.</p>}</section><section className="note-section"><label className="field-label" htmlFor="reminder-note">Reminder Notes</label><KeyboardInput id="reminder-note" aria-label="Reminder Notes" maxLength={120} value={r.note} onChange={e=>patch({note:e.target.value})} className="text-field" onKeyDown={e=>{if(e.key==='Enter')keyboard.hide();}}/><p className="helper">The above text appears the reminder title</p></section><div className="info-box"><Icon name="info" size={20}/><p>{reminderSummary(r)} <span className="reminder-summary-hint">To change it, go to advanced settings.</span></p></div><section className="advanced-settings"><button className="advanced-toggle" aria-expanded={advanced} onClick={()=>{keyboard.hide();setAdvanced(!advanced);}}>Advanced Settings<Icon name="chevron" size={16} className={advanced?'':'flip-y'}/></button>{advanced&&<div className="advanced-body"><label className="field-label">Start Date</label><button className="date-field" onClick={()=>setDateEdit('start')}><span>{dateLabel(r.start)}</span><Icon name="calendar" size={20}/></button><div className="end-label"><label className="field-label">End Date</label><label className="ends-never"><span className="ends-never-control"><input type="checkbox" checked={r.never} onChange={e=>patch({never:e.target.checked,end:r.end<r.start?r.start:r.end})}/>{r.never?<CheckCircledIcon width="18" height="18"/>:<img src={A+'4f9da.svg'} width="18" height="18" alt=""/>}</span>Ends Never</label></div><button className="date-field" disabled={r.never} onClick={()=>setDateEdit('end')}><span>{dateLabel(r.end)}</span><Icon name="calendar" size={20}/></button><h2>Repeat Schedule</h2><div className="repeat-options" role="radiogroup" aria-label="Repeat Schedule">{(['daily','selected'] as const).map(type=><button key={type} role="radio" aria-checked={r.repeat===type} className={'repeat-option '+(r.repeat===type?'selected':'')} onClick={()=>patch({repeat:type})}><span><strong>{type==='daily'?'Every day':'Selected days'}</strong><small>{type==='daily'?'Repeats everyday of the week':'Choose days of the week'}</small></span>{r.repeat===type?<CheckCircledIcon width="22" height="22"/>:<CircleIcon width="22" height="22"/>}</button>)}</div>{r.repeat==='selected'&&<div className="weekday-list">{weekdays.map((d,i)=><button key={d} aria-label={d} aria-pressed={r.days.includes(i)} onClick={()=>patch({days:r.days.includes(i)?r.days.filter(j=>j!==i):[...r.days,i].sort()})}>{d.slice(0,1)}</button>)}</div>}{r.repeat==='selected'&&r.days.length===0&&<p className="field-error">Choose at least one day.</p>}</div>}</section></main></MobileScroll><BottomSheet open={timeEdit!==null} onOpenChange={o=>{if(!o)setTimeEdit(null);}} title={adding?'Add Reminder Time':'Edit Reminder Time'} description="Choose when you would like to be reminded." snap={0.43}><button className="sheet-close icon-button" aria-label="Close time picker" onClick={()=>setTimeEdit(null)}><Icon name="close" size={24}/></button>{timeEdit!==null&&<TimePicker key={timeEdit} initial={adding?'09:00':r.times[timeEdit]} onCancel={()=>setTimeEdit(null)} onSave={value=>{if(r.times.some((t,i)=>t===value&&i!==timeEdit)){setTimeError('This reminder time already exists. Choose another time.');return;}patch({times:(adding?[...r.times,value]:r.times.map((t,i)=>i===timeEdit?value:t)).sort()});setTimeEdit(null);}}/>}{timeError&&<p className="field-error" role="alert">{timeError}</p>}</BottomSheet><BottomSheet open={dateEdit!==null} onOpenChange={o=>{if(!o)setDateEdit(null);}} title={dateEdit==='start'?'Start Date':'End Date'} description="Choose a date for your reminder." snap={0.64}><button className="sheet-close icon-button" aria-label="Close calendar" onClick={()=>setDateEdit(null)}><Icon name="close" size={24}/></button>{dateEdit&&<Calendar key={dateEdit} value={r[dateEdit]} min={dateEdit==='end'?r.start:undefined} onSelect={value=>{patch(dateEdit==='start'?{start:value,end:value}:{end:value});setDateEdit(null);}}/>}</BottomSheet></>;
}
function SetupFooter(){const store=useStore(),flow=useFlow();const{draft:r}=store;const disabled=!r.times.length||!r.note.trim()||(r.repeat==='selected'&&!r.days.length)||(!r.never&&r.end<r.start);return <div className="setup-footer"><button className="primary-button" disabled={disabled} onClick={()=>{store.setReminder({...structuredClone(r),note:r.note.trim()});flow.pop();store.notify(store.reminder?'Reminder updated':'Fluid intake reminder set');}}>{store.reminder?'Save Reminder Changes':'Set Fluid Intake Reminder'}</button></div>;}
const homeScreen:FlowScreen={id:'home',headerHeight:52,header:()=> <HomeHeader/>,render:()=> <Home/>};
const detailsScreen:FlowScreen={id:'details',headerHeight:84,header:()=> <Header/>,render:()=> <Details/>};
const setupScreen:FlowScreen={id:'setup',headerHeight:52,header:()=> <Header reminder/>,footerHeight:60,footer:()=> <SetupFooter/>,render:()=> <Setup/>};

// Medication Handoff: shared dose records are independent of fluid-intake readings.
type MedicationType='Capsule'|'Tablet'|'Liquid'|'Injection';
type Medication={id:string;name:string;strength:string;type:MedicationType|'';amount:string;frequency:string;times:string[];conditions:string[];notes:string;image:string;imageName:string;schedule:Reminder;hasSchedule:boolean;reminders:boolean};
type Dose={medication:Medication;time:string;key:string};
type MedicationStore={medications:Medication[];setMedications:React.Dispatch<React.SetStateAction<Medication[]>>;taken:Record<string,boolean>;setTaken:React.Dispatch<React.SetStateAction<Record<string,boolean>>>;notifications:boolean;setNotifications:React.Dispatch<React.SetStateAction<boolean>>;editor:Medication;setEditor:React.Dispatch<React.SetStateAction<Medication>>;phase:number;setPhase:React.Dispatch<React.SetStateAction<number>>;editing:boolean;setEditing:React.Dispatch<React.SetStateAction<boolean>>;reset:()=>void;loadExample:()=>void};
const MedicationContext=createContext<MedicationStore>(null!);
const useMedications=()=>useContext(MedicationContext);
const newMedication=():Medication=>({id:crypto.randomUUID(),name:'',strength:'',type:'',amount:'',frequency:'',times:[],conditions:[],notes:'',image:'',imageName:'',schedule:{...freshReminder(),times:[],days:[0,2,4],never:false},hasSchedule:true,reminders:false});
function isScheduled(m:Medication,date:string){return m.hasSchedule&&date>=m.schedule.start&&(m.schedule.never||date<=m.schedule.end)&&(m.schedule.repeat==='daily'||m.schedule.days.includes((new Date(date+'T12:00:00').getDay()+6)%7));}
function scheduledDoses(medications:Medication[],date:string):Dose[]{return medications.filter(m=>isScheduled(m,date)).flatMap(m=>m.times.map(time=>({medication:m,time,key:`${m.id}|${date}|${time}`}))).sort((a,b)=>a.time.localeCompare(b.time)||a.medication.name.localeCompare(b.medication.name));}
function medicationProgress(medications:Medication[],taken:Record<string,boolean>,date:string){const doses=scheduledDoses(medications,date);const count=doses.filter(d=>taken[d.key]).length;return{total:doses.length,count,percent:doses.length?Math.round(count/doses.length*100):0};}
function MedicationProvider({children}:{children:React.ReactNode}){
 const[medications,setMedications]=useState<Medication[]>([]),[taken,setTaken]=useState<Record<string,boolean>>({}),[notifications,setNotifications]=useState(true),[editor,setEditor]=useState(newMedication),[phase,setPhase]=useState(1),[editing,setEditing]=useState(false);
 const reset=()=>{setMedications([]);setTaken({});setNotifications(true);setEditor(newMedication());setPhase(1);setEditing(false);};
 const loadExample=()=>{const make=(name:string,type:MedicationType,times:string[],image=''):Medication=>({...newMedication(),name,type,strength:type==='Liquid'?'150':'500',amount:type==='Liquid'?'10':'1',frequency:String(times.length),times,conditions:type==='Liquid'?['Asthma']:['Pneumonia'],notes:'I have to take this medicine on time',image,imageName:image?'Medication photo':'',reminders:true,schedule:{...freshReminder(),times:[],never:true}});const examples=[make('Amoxicillin','Capsule',['09:00','13:00','22:00']),make('Amitriptyline','Tablet',['09:00','20:00'],A+'f5c4f.png'),make('Salbutamol','Liquid',['09:00','20:00'])];const done:Record<string,boolean>={};for(const m of examples.slice(0,2))done[`${m.id}|${today}|09:00`]=true;done[`${examples[0].id}|${today}|13:00`]=true;examples[2].reminders=false;setMedications(examples);setTaken(done);};
 return <MedicationContext.Provider value={{medications,setMedications,taken,setTaken,notifications,setNotifications,editor,setEditor,phase,setPhase,editing,setEditing,reset,loadExample}}>{children}</MedicationContext.Provider>;
}
function MedAsset({file,slot=20,className=''}:{file:string;slot?:number;className?:string}){return <span className={'med-asset '+className} style={{width:slot,height:slot}}><img src={A+file} alt="" draggable={false}/></span>;}
function HealthCategories({active}:{active:'Medication'|'Fluid Intake'}){const flow=useFlow();const tabs=['Medication','Fluid Intake','Appointments','Steps','Calories','Exercise','Sleep','Meditation'];return <Carousel ariaLabel="Health categories" className="category-tabs" contentClassName="category-track">{tabs.map(t=>['Medication','Fluid Intake'].includes(t)?<button className={'category '+(active===t?'active':'')} key={t} aria-current={active===t?'page':undefined} onClick={()=>{if(t!==active)flow.replace(t==='Medication'?medicationScreen:detailsScreen);}}>{t}</button>:<span className="category" key={t}>{t}</span>)}</Carousel>;}
function MedicationHeader(){const flow=useFlow(),chrome=useScrollChrome();return <div className="emp-header health-category-header" data-scrolled={chrome.scrolled} data-more-below={chrome.moreBelow}><div className="nav-row"><button className="icon-button" aria-label="Go back" onClick={flow.pop}><Icon name="back" size={24}/></button><button className="icon-button" aria-label="View medication progress" onClick={()=>{if(flow.current.id!=='medication')flow.pop();else document.querySelector('[data-flow-current="true"] .med-progress')?.scrollIntoView({behavior:'smooth'});}}><Icon name="chart" size={24}/></button></div><HealthCategories active="Medication"/></div>;}
function MedicationRing({percent,size=72}:{percent:number;size?:number}){const ref=useRef<HTMLCanvasElement>(null);useEffect(()=>{if(!ref.current)return;const teal=getComputedStyle(ref.current).getPropertyValue('--base-color-teal-90').trim();const chart=new Chart(ref.current,{type:'doughnut',data:{datasets:[{data:[percent,100-percent],backgroundColor:[teal,'#f4f5f5'],borderWidth:0,hoverOffset:0}]},options:{responsive:false,animation:false,events:[],cutout:'93%',plugins:{legend:{display:false},tooltip:{enabled:false}}}});return()=>chart.destroy();},[percent]);return <div className="med-ring" style={{width:size,height:size}} role="img" aria-label={`${percent}% of medication doses taken`}><canvas ref={ref} width={size} height={size}/><span>{percent}%</span></div>;}
function beginMedication(flow:ReturnType<typeof useFlow>,store:MedicationStore,medication?:Medication,phase=1){store.setEditor(structuredClone(medication??newMedication()));store.setEditing(!!medication);store.setPhase(phase);flow.push(medicationEditorScreen);}
function MedicationWizardHeader({scheduleOnly=false}:{scheduleOnly?:boolean}){const store=useMedications(),flow=useFlow(),keyboard=useKeyboard(),chrome=useScrollChrome();const title=scheduleOnly?'Update Schedule':store.phase<4?(store.editing?'Update Medication Details':'Add Medication Details'):store.phase===4?'Medication Schedule':'Review Medication Details';return <div className={'med-wizard-header '+(scheduleOnly?'med-schedule-only':'')} data-scrolled={chrome.scrolled} data-more-below={chrome.moreBelow}><div className="med-titlebar"><button className="icon-button" aria-label="Go back" onClick={()=>{keyboard.hide();if(!scheduleOnly&&store.phase>1)store.setPhase(p=>p-1);else flow.pop();}}><MedAsset file="5824e.svg" slot={24}/></button><h1>{title}</h1></div>{!scheduleOnly&&<div className="med-form-progress" aria-label={`Medication setup, ${store.phase<4?'Medication Details':store.phase===4?'Schedule':'Review'}`} >{['Medication Details','Schedule','Review'].map((t,i)=><div key={t} className={i<=(store.phase<4?0:store.phase===4?1:2)?'complete':''}><span/><small>{t}</small></div>)}</div>}</div>;}
function NotificationSettings({open,onOpenChange}:{open:boolean;onOpenChange:(v:boolean)=>void}){const s=useMedications();return <BottomSheet open={open} onOpenChange={onOpenChange} title="Notification Settings" snap={0.4}><button className="sheet-close icon-button" aria-label="Close notification settings" onClick={()=>onOpenChange(false)}><Icon name="close" size={24}/></button><p className="med-permission-copy">Notification reminders help you keep track of your medication schedule.</p><button className="med-reminder-switch" role="switch" aria-checked={s.notifications} onClick={()=>s.setNotifications(v=>!v)}><span>Allow Notifications</span><MedAsset file={s.notifications?'33b4d.svg':'a0851.svg'} slot={44}/></button><button className="primary-button" onClick={()=>onOpenChange(false)}>Done</button></BottomSheet>;}
function NotificationWarning(){const s=useMedications();const[open,setOpen]=useState(false),[dismissed,setDismissed]=useState(false);useEffect(()=>setDismissed(false),[s.notifications]);return <>{!s.notifications&&!dismissed&&<div className="med-notification-warning"><MedAsset file="f7917.svg" slot={32}/><div><strong>Enable Notifications</strong><p>Notification reminders help you keep track of your medication schedule</p><button onClick={()=>setOpen(true)}>Edit Notification Settings</button></div><button className="med-warning-dismiss" aria-label="Dismiss notification warning" onClick={()=>setDismissed(true)}><MedAsset file="05290.svg" slot={24}/></button></div>}<NotificationSettings open={open} onOpenChange={setOpen}/></>;}

function MedicationReminderSwitch({value,onChange}:{value:boolean;onChange:(v:boolean)=>void}){const s=useMedications();return <><NotificationWarning/><button className="med-reminder-switch" role="switch" aria-label="Remind me at scheduled times" aria-checked={value&&s.notifications} disabled={!s.notifications} onClick={()=>onChange(!value)}><span>Remind me at scheduled times</span><MedAsset file={value&&s.notifications?'33b4d.svg':'a0851.svg'} slot={44}/></button></>;}
function MedicationField({label,required=false,helper,children}:{label:string;required?:boolean;helper?:string;children:React.ReactNode}){return <div className="med-field"><label className="med-label">{label}{required&&<span className="med-required"> *</span>}</label>{children}{helper&&<p className="med-helper">{helper}</p>}</div>;}
function MedicationWizard(){
 const s=useMedications(),keyboard=useKeyboard(),{notify}=useStore();const m=s.editor;const patch=(v:Partial<Medication>)=>s.setEditor(p=>({...p,...v}));const[addCondition,setAddCondition]=useState(false),[condition,setCondition]=useState(''),[chooseCondition,setChooseCondition]=useState(false),[typeOpen,setTypeOpen]=useState(false),[timeIndex,setTimeIndex]=useState<number|null>(null),[timeError,setTimeError]=useState(''),[fileError,setFileError]=useState('');const fileRef=useRef<HTMLInputElement>(null);const timeChange=useKeyboardSheet(timeIndex!==null,o=>{if(!o)setTimeIndex(null);});
 useEffect(()=>{document.querySelector('[data-flow-current="true"] .mobile-scroll')?.scrollTo({top:0});},[s.phase]);
 const addNewCondition=()=>{const value=condition.trim();if(value&&!m.conditions.some(c=>c.toLowerCase()===value.toLowerCase()))patch({conditions:[...m.conditions,value]});setCondition('');setAddCondition(false);keyboard.hide();};
 return <><MobileScroll className="medication-scroll"><main className={'med-wizard-content '+(s.phase===5?'med-review-content':'')}>
 {s.phase<4&&<div className="med-step-heading"><small>Medication · {s.phase} of 3</small><h2>{s.phase===1?'Which medication?':s.phase===2?'Dosage & Schedule':'What are you taking for ?'}</h2><p>{s.phase===1?'Use the name on your medication label.':s.phase===2?'Enter the medication dosage & schedule':'Choose a condition related to the medication.'}</p></div>}
 {s.phase===1&&<div className="med-fields"><MedicationField label="Medication name" required helper="Example : Amitriptyline"><KeyboardInput aria-label="Medication name" className="med-input" placeholder="Enter the medication name" value={m.name} onChange={e=>patch({name:e.target.value})} maxLength={100}/></MedicationField><MedicationField label="Medication Strength" required helper="Please enter the value in mg"><KeyboardInput aria-label="Medication Strength" inputMode="decimal" className="med-input" placeholder="Enter the medication strength" value={m.strength} onChange={e=>{if(/^[\d\s.,+\-/%()]*$/.test(e.target.value))patch({strength:e.target.value});}} maxLength={30}/></MedicationField><MedicationField label="Medication Type" required helper="Choose the type of the medication"><button className="med-input med-select" aria-haspopup="listbox" aria-label="Medication Type" onClick={()=>{keyboard.hide();setTypeOpen(true);}}><span className={!m.type?'med-placeholder':''}>{m.type||'Choose the medication type'}</span><MedAsset file="19a0b.svg" slot={20}/></button></MedicationField><MedicationField label="Medication Image"><div className="med-upload-row"><input ref={fileRef} type="file" accept="image/*" hidden aria-label="Upload medication image" onChange={e=>{const file=e.target.files?.[0];setFileError('');if(!file)return;if(!file.type.startsWith('image/')){setFileError('Choose an image file.');return;}const reader=new FileReader();reader.onerror=()=>setFileError('The image could not be opened. Please try again.');reader.onload=()=>patch({image:String(reader.result),imageName:file.name});reader.readAsDataURL(file);e.target.value='';}}/><button className="med-upload" onClick={()=>{keyboard.hide();fileRef.current?.click();}}><MedAsset file="f9dff.svg" slot={24}/>Upload</button><button className="med-camera" aria-label="Camera, available in the mobile app" onClick={()=>notify('Camera is available in the mobile app')}><MedAsset file="1e21c.svg" slot={48}/></button></div>{m.image&&<div className="med-uploaded"><img src={m.image} alt="Uploaded medication"/><div><span>{m.imageName}</span><small>Upload successful</small></div><button className="icon-button" aria-label="Remove medication image" onClick={()=>patch({image:'',imageName:''})}><MedAsset file="31029.svg"/></button></div>}{fileError&&<p className="field-error">{fileError}</p>}</MedicationField></div>}
 {s.phase===2&&<div className="med-fields"><MedicationField label="Usual amount per dose" required helper="The amount to be taken per serving"><KeyboardInput aria-label="Usual amount per dose" className="med-input" inputMode="decimal" value={m.amount} onChange={e=>{if(/^\d*\.?\d*$/.test(e.target.value))patch({amount:e.target.value});}}/></MedicationField><MedicationField label="Daily Medication Frequency" required helper="How many times a day to take this medication"><KeyboardInput aria-label="Daily Medication Frequency" className="med-input" inputMode="numeric" value={m.frequency} onChange={e=>{if(/^\d{0,4}$/.test(e.target.value)){const frequency=e.target.value;patch({frequency,times:m.times.slice(0,Number(frequency))});}}}/></MedicationField><div className="med-dose-times">{m.times.map((t,i)=><div className="time-chip" key={t}><button className="time-edit" aria-label={'Edit dose time '+timeLabel(t)} onClick={()=>{setTimeError('');setTimeIndex(i);}}><MedAsset file="0fe3b.svg" slot={16}/><span>{timeLabel(t,false)}</span></button><button className="time-remove" aria-label={'Remove dose time '+timeLabel(t)} onClick={()=>patch({times:m.times.filter((_,j)=>j!==i)})}><Icon name="close" size={14}/></button></div>)}<button className="outline-button" disabled={!Number(m.frequency)||m.times.length>=Number(m.frequency)||Number(m.frequency)>1440} onClick={()=>{setTimeError('');setTimeIndex(-1);}}>Add Time <MedAsset file="73593.svg" slot={20}/></button><p className="med-helper">All times are required to continue. For example, if you take it 3 times a day, add 3 times to proceed.</p></div></div>}
 {s.phase===3&&<div className="med-fields"><MedicationField label="Related Conditions" helper="Choose the related conditions to the medication"><div className="med-condition-box" onClick={e=>{if(e.target===e.currentTarget)setChooseCondition(true);}}>{m.conditions.map(c=><span className="med-condition-chip" key={c}>{c}<button aria-label={'Remove condition '+c} onClick={()=>patch({conditions:m.conditions.filter(x=>x!==c)})}><MedAsset file="e6b0c.svg" slot={14}/></button></span>)}<button className={'med-condition-choose '+(m.conditions.length?'med-condition-more':'')} aria-label="Choose related conditions" onClick={()=>setChooseCondition(true)}>{m.conditions.length?'':'Choose related conditions'}</button></div></MedicationField>{addCondition?<div className="med-add-condition"><KeyboardInput aria-label="New condition" className="med-input" placeholder="Enter condition" value={condition} onChange={e=>setCondition(e.target.value)} maxLength={80} onKeyDown={e=>{if(e.key==='Enter')addNewCondition();}}/><button className="icon-button" aria-label="Confirm new condition" disabled={!condition.trim()} onClick={addNewCondition}><CheckCircledIcon width={22} height={22}/></button><button className="icon-button" aria-label="Cancel new condition" onClick={()=>{setAddCondition(false);setCondition('');keyboard.hide();}}><Icon name="close"/></button></div>:<button className="outline-button med-add-condition-button" onClick={()=>setAddCondition(true)}>Add Condition <MedAsset file="aaca1.svg" slot={20}/></button>}<MedicationField label="Notes"><KeyboardTextarea aria-label="Medication Notes" className="med-input med-notes" placeholder="I need to take this medication" value={m.notes} onChange={e=>patch({notes:e.target.value})} maxLength={500}/></MedicationField></div>}
 {s.phase===4&&<MedicationScheduleFields/>}{s.phase===5&&<MedicationReview/>}
 </main></MobileScroll>
 <BottomSheet open={typeOpen} onOpenChange={setTypeOpen} title="Medication Type" snap={0.48}><button className="sheet-close icon-button" aria-label="Close medication types" onClick={()=>setTypeOpen(false)}><Icon name="close" size={24}/></button><div role="listbox" aria-label="Medication types" className="med-type-options">{(['Capsule','Tablet','Liquid','Injection'] as const).map(t=><button role="option" aria-selected={m.type===t} key={t} onClick={()=>{patch({type:t});setTypeOpen(false);}}>{t}{m.type===t&&<CheckCircledIcon width={20} height={20}/>}</button>)}</div></BottomSheet>
 <BottomSheet open={chooseCondition} onOpenChange={setChooseCondition} title="Related Conditions" snap={0.6}><button className="sheet-close icon-button" aria-label="Close related conditions" onClick={()=>setChooseCondition(false)}><Icon name="close" size={24}/></button><div className="med-type-options">{['Asthma','Bronchitis','Chronic Kidney Disease','Epilepsy','Diabetes','Pneumonia'].map(c=><button key={c} role="checkbox" aria-checked={m.conditions.includes(c)} onClick={()=>patch({conditions:m.conditions.includes(c)?m.conditions.filter(x=>x!==c):[...m.conditions,c]})}>{c}{m.conditions.includes(c)?<CheckCircledIcon width={20} height={20}/>:<CircleIcon width={20} height={20}/>}</button>)}</div><button className="primary-button" onClick={()=>setChooseCondition(false)}>Done</button></BottomSheet>
 <BottomSheet open={timeIndex!==null} onOpenChange={timeChange} title={timeIndex===-1?'Add Medication Time':'Edit Medication Time'} snap={0.43}><button className="sheet-close icon-button" aria-label="Close medication time picker" onClick={()=>setTimeIndex(null)}><Icon name="close" size={24}/></button>{timeIndex!==null&&<TimePicker key={timeIndex} initial={timeIndex===-1?'09:00':m.times[timeIndex]} onCancel={()=>setTimeIndex(null)} onSave={time=>{if(m.times.some((t,i)=>t===time&&i!==timeIndex)){setTimeError('Choose a different time. Each medication time must be unique.');return;}patch({times:(timeIndex===-1?[...m.times,time]:m.times.map((t,i)=>i===timeIndex?time:t)).sort()});setTimeIndex(null);}}/>}{timeError&&<p className="field-error" role="alert">{timeError}</p>}</BottomSheet>
 </>;
}
function MedicationScheduleFields({update=false}:{update?:boolean}){
 const s=useMedications(),m=s.editor,r=m.schedule;const[dateEdit,setDateEdit]=useState<'start'|'end'|null>(null);const patch=(v:Partial<Reminder>)=>s.setEditor(p=>({...p,schedule:{...p.schedule,...v}}));
 return <div className="med-schedule-fields"><MedicationField label="Start Date" required={!update}><button className="date-field" aria-label={'Medication start date '+dateLabel(r.start)} onClick={()=>setDateEdit('start')}><span>{dateLabel(r.start)}</span><MedAsset file="29ea4.svg"/></button></MedicationField><div className="med-field"><div className="med-end-label"><label className="med-label">End Date</label><button role="checkbox" aria-checked={r.never} className="med-never" onClick={()=>patch({never:!r.never})}>{r.never?<CheckCircledIcon width={18} height={18}/>:<CircleIcon width={18} height={18}/>}Ends Never</button></div><button className="date-field" aria-label={'Medication end date '+dateLabel(r.end)} disabled={r.never} onClick={()=>setDateEdit('end')}><span>{dateLabel(r.end)}</span><MedAsset file="29ea4.svg"/></button></div><div className="med-field"><h2 className="med-label">Repeat Schedule</h2><div className="med-repeat-options" role="radiogroup" aria-label="Medication repeat schedule">{(['daily','selected'] as const).map(type=><button key={type} role="radio" aria-checked={r.repeat===type} className={'med-repeat-option '+(r.repeat===type?'selected':'')} onClick={()=>patch({repeat:type})}><span><strong>{type==='daily'?'Every day':'Selected days'}</strong><small>{type==='daily'?'Repeats everyday of the week':'Choose days of the week'}</small></span><MedAsset file={r.repeat===type?'f6cde.svg':'4b7ef.svg'} slot={22}/></button>)}</div>{r.repeat==='selected'&&<div className="med-weekdays">{weekdays.map((d,i)=><button key={d} aria-label={d} aria-pressed={r.days.includes(i)} onClick={()=>patch({days:r.days.includes(i)?r.days.filter(j=>j!==i):[...r.days,i].sort()})}>{d[0]}</button>)}</div>}{r.repeat==='selected'&&!r.days.length&&<p className="field-error">Choose at least one day.</p>}</div>{!update&&<MedicationReminderSwitch value={m.reminders} onChange={reminders=>s.setEditor(p=>({...p,reminders}))}/>}<BottomSheet open={dateEdit!==null} onOpenChange={o=>{if(!o)setDateEdit(null);}} title={dateEdit==='start'?'Start Date':'End Date'} snap={0.64}><button className="sheet-close icon-button" aria-label="Close medication calendar" onClick={()=>setDateEdit(null)}><Icon name="close" size={24}/></button>{dateEdit&&<Calendar key={dateEdit} value={r[dateEdit]} min={dateEdit==='end'?r.start:undefined} onSelect={date=>{patch(dateEdit==='start'?{start:date,end:date}:{end:date});setDateEdit(null);}}/>}</BottomSheet></div>;
}
function medStrength(m:Medication){return `${m.strength} ${m.type==='Liquid'?'ml':'mg'}`;}
function medAmount(m:Medication,full=false){return `${m.amount}${m.type==='Liquid'?' ml':''} ${full?m.type:m.type.toLowerCase()}${full?' Per Serving':''}`;}
function MedicationArt({medication:m,small=false,dose=false}:{medication:Medication;small?:boolean;dose?:boolean}){return small?<span className={'med-small-art '+(dose&&!m.image?'med-dose-art':'')}>{m.image?<img src={m.image} alt=""/>:m.type==='Liquid'?<img className="med-liquid-image" src={A+'c4624.svg'} alt=""/>:dose?<img src={A+'7d747.png'} alt=""/>:<img src={A+'a6c0c.svg'} alt=""/>}</span>:<div className={'medication-art med-art-'+m.type.toLowerCase()}>{m.image?<img className={'med-user-photo '+(m.image.startsWith(A)?'med-reference-photo':'')} src={m.image} alt={m.name}/>:m.type==='Capsule'?<img src={A+'d9216.svg'} alt=""/>:m.type==='Tablet'?<img className="med-tablet-image" src={A+'484be.svg'} alt=""/>:m.type==='Liquid'?<img className="med-liquid-image" src={A+'c4624.svg'} alt=""/>:<MedAsset file="b99b9.svg" slot={64}/>}</div>;}
function MedicationIdentity({medication:m,full=false}:{medication:Medication;full?:boolean}){return <div className="med-identity"><div className="med-name"><span>{m.name}</span><small>{medStrength(m)}</small></div><p className="med-meta"><MedAsset file="47d09.svg" slot={16}/>{medAmount(m,full)}</p>{m.conditions.length>0&&<p className="med-meta"><MedAsset file="99980.svg" slot={16}/>{m.conditions.join(', ')}</p>}</div>;}
function MedicationScheduleSummary({medication:m,review=false}:{medication:Medication;review?:boolean}){return m.hasSchedule?<div className={'med-schedule-summary '+(review?'review':'')}><div className="med-date-summary"><span><MedAsset file={review?'c2fd9.svg':'f2f3e.svg'} slot={review?20:14}/>{dateLabel(m.schedule.start)}</span><span>→</span><span>{!m.schedule.never&&<MedAsset file={review?'f29f9.svg':'f2f3e.svg'} slot={review?20:14}/>} {m.schedule.never?(review?'Ends Never':'Not Mentioned'):dateLabel(m.schedule.end)}</span></div>{review?<><p className="med-repeat-summary"><MedAsset file="c6ed2.svg" slot={16}/>{repeatLabel(m.schedule)}</p><div className="med-review-times">{m.times.map(t=><span key={t}><MedAsset file="426f2.svg" slot={16}/>{timeLabel(t)}</span>)}</div></>:<p className="med-list-repeat">{m.schedule.repeat==='daily'?'Everyday':m.schedule.days.map(d=>weekdays[d].slice(0,3)).join(', ')} at {m.times.map(t=>timeLabel(t)).join(', ')}</p>}</div>:<p className="med-no-schedule">No schedule set</p>;}
function MedicationReview(){const s=useMedications(),flow=useFlow(),m=s.editor;return <><div className="med-review-identity"><MedicationArt medication={m}/><MedicationIdentity medication={m} full/></div>{m.notes&&<p className="med-review-note">Note : {m.notes}</p>}<section className="med-review-schedule"><h2>Schedule</h2>{m.hasSchedule?<><button className="med-edit-schedule icon-button" aria-label="Edit medication schedule" onClick={()=>flow.push(medicationUpdateScheduleScreen)}><MedAsset file="71da2.svg" slot={24}/></button><MedicationScheduleSummary medication={m} review/></>:<button className="outline-button" onClick={()=>{s.setEditor(p=>({...p,hasSchedule:true}));s.setPhase(4);}}>Set Up Schedule</button>}</section>{m.hasSchedule&&<MedicationReminderSwitch value={m.reminders} onChange={reminders=>s.setEditor(p=>({...p,reminders}))}/>}</>;}
const validMedicationDetails=(m:Medication)=>!!m.name.trim()&&/\d/.test(m.strength)&&!!m.type;
const validMedicationDose=(m:Medication)=>Number(m.amount)>0&&Number.isInteger(Number(m.frequency))&&Number(m.frequency)>0&&m.times.length===Number(m.frequency)&&new Set(m.times).size===m.times.length;
const validMedicationSchedule=(m:Medication)=>!!m.schedule.start&&(m.schedule.never||m.schedule.end>=m.schedule.start)&&(m.schedule.repeat==='daily'||m.schedule.days.length>0);
function MedicationWizardFooter(){const s=useMedications(),flow=useFlow(),keyboard=useKeyboard(),{notify}=useStore();const m=s.editor;const disabled=s.phase===1?!validMedicationDetails(m):s.phase===2?!validMedicationDose(m):s.phase===4?!validMedicationSchedule(m):s.phase===5?(!validMedicationDetails(m)||!validMedicationDose(m)||(m.hasSchedule&&!validMedicationSchedule(m))):false;const labels=['Continue to Dosage & Schedule','Continue To Condition Details','Continue to Set Schedule','Set Schedule',s.editing?'Save Medication Changes':'Save Medication'];return <div className="setup-footer med-footer"><button className="primary-button" disabled={disabled} onClick={()=>{keyboard.hide();if(s.phase<5){s.setPhase(p=>p+1);return;}const saved={...structuredClone(m),name:m.name.trim(),strength:m.strength.trim(),schedule:{...m.schedule,times:[...m.times]},reminders:m.hasSchedule&&m.reminders};s.setMedications(current=>s.editing?current.map(p=>p.id===m.id?saved:p):[...current,saved]);flow.pop();notify(s.editing?'Medication updated':'Medication added');}}>{labels[s.phase-1]}</button></div>;}
function MedicationConfirm({open,onOpenChange,kind,onConfirm}:{open:boolean;onOpenChange:(v:boolean)=>void;kind:'medication'|'Schedule';onConfirm:()=>void}){const{screenRef}=useScreenPortal();const keyboard=useKeyboard();useEffect(()=>{if(open)keyboard.hide();},[open]);return <Dialog.Root open={open} onOpenChange={onOpenChange}><Dialog.Portal container={screenRef.current??undefined}><Dialog.Overlay className="med-confirm-overlay"/><Dialog.Content className="med-confirm"><Dialog.Title>Delete this {kind} permanently ?</Dialog.Title><Dialog.Description>{kind==='medication'?'Deleting the medication will remove it from the list and your daily medication schedule':'Deleting this schedule will remove it from your daily schedule.'}</Dialog.Description><div><Dialog.Close asChild><button className="med-cancel">Cancel</button></Dialog.Close><button className="med-danger" onClick={onConfirm}>Delete {kind==='medication'?'Medication':'Schedule'}</button></div></Dialog.Content></Dialog.Portal></Dialog.Root>;}
function MedicationUpdateSchedule(){return <MobileScroll className="medication-scroll"><main className="med-wizard-content med-update-schedule"><MedicationScheduleFields update/></main></MobileScroll>;}
function MedicationUpdateScheduleFooter(){const s=useMedications(),flow=useFlow();const[confirm,setConfirm]=useState(false);return <div className="setup-footer med-footer med-update-footer"><button className="outline-button med-delete-schedule" onClick={()=>setConfirm(true)}>Delete Schedule</button><button className="primary-button" disabled={!validMedicationSchedule(s.editor)} onClick={flow.pop}>Update Schedule</button><MedicationConfirm open={confirm} onOpenChange={setConfirm} kind="Schedule" onConfirm={()=>{s.setEditor(p=>({...p,hasSchedule:false,reminders:false}));setConfirm(false);flow.pop();}}/></div>;}
function MedicationCard({medication:m,compact=false}:{medication:Medication;compact?:boolean}){
 const s=useMedications(),flow=useFlow(),keyboard=useKeyboard(),{notify}=useStore();const[menu,setMenu]=useState(false),[menuAbove,setMenuAbove]=useState(false),[confirm,setConfirm]=useState(false);const menuRef=useRef<HTMLDivElement>(null);
 useEffect(()=>{if(!menu)return;const outside=(e:PointerEvent)=>{if(e.target instanceof Node&&!menuRef.current?.contains(e.target))setMenu(false);};const escape=(e:KeyboardEvent)=>{if(e.key==='Escape')setMenu(false);};document.addEventListener('pointerdown',outside,true);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('pointerdown',outside,true);document.removeEventListener('keydown',escape);};},[menu]);
 const edit=()=>{setMenu(false);beginMedication(flow,s,m);};
 return <article className={compact?'med-compact-card':'med-list-card'}><button className="med-card-hit" aria-label={'Edit medication '+m.name} onClick={edit}/>{compact?<><div className="med-compact-name"><MedicationArt medication={m} small/><strong>{m.name}</strong><small>{medStrength(m)}</small></div><div className="med-compact-meta"><span><MedAsset file="1015f.svg" slot={14}/>{medAmount(m)}</span>{m.conditions.length>0&&<span><MedAsset file="82427.svg" slot={14}/>{m.conditions.join(', ')}</span>}</div></>:<><MedicationArt medication={m}/><MedicationIdentity medication={m} full/></>}
 <div className="med-card-schedule"><MedicationScheduleSummary medication={m}/></div>{m.notes&&<p className="med-card-note">Note : {m.notes}</p>}
 <div className="med-card-controls">{compact&&<button className="icon-button med-card-edit" aria-label={'Edit '+m.name} onClick={edit}><MedAsset file="71da2.svg" slot={24}/></button>}<div className="med-menu-anchor" ref={menuRef}><button className="med-menu-trigger" aria-label={'Options for '+m.name} aria-haspopup="menu" aria-expanded={menu} onClick={()=>{keyboard.hide();const bounds=menuRef.current?.getBoundingClientRect();const viewport=menuRef.current?.closest('.flow-stack');const screen=viewport?.getBoundingClientRect();const footer=viewport?parseFloat(getComputedStyle(viewport).getPropertyValue('--flow-footer-height'))||0:0;setMenuAbove(!!bounds&&!!screen&&screen.bottom-bounds.bottom-footer<(compact?104:140));setMenu(v=>!v);}}><MedAsset file={compact?'647d4.svg':'5bc25.svg'} slot={24}/></button>{menu&&<div className={'med-card-menu '+(menuAbove?'med-menu-above':'')} role="menu" aria-label={m.name+' options'}>{!compact&&<button role="menuitem" onClick={edit}>Edit Medication<MedAsset file="71da2.svg"/></button>}<button role="menuitem" onClick={()=>{setMenu(false);beginMedication(flow,s,{...m,hasSchedule:true,reminders:true},4);}}>Set Up Reminders<MedAsset file="0a302.svg"/></button><button role="menuitem" onClick={()=>{setMenu(false);setConfirm(true);}}>Delete Medication<MedAsset file="31029.svg"/></button></div>}</div></div>
 <MedicationConfirm open={confirm} onOpenChange={setConfirm} kind="medication" onConfirm={()=>{s.setMedications(current=>current.filter(p=>p.id!==m.id));s.setTaken(current=>Object.fromEntries(Object.entries(current).filter(([key])=>!key.startsWith(m.id+'|'))));setConfirm(false);notify('Medication deleted');}}/></article>;
}
function YourMedicationsPanel(){const s=useMedications(),flow=useFlow();return <section className="med-your-panel"><div className="med-your-title"><h2><MedAsset file="c0498.svg"/>Your Medications</h2><button className="primary-button" onClick={()=>beginMedication(flow,s)}>Add Medication</button></div>{s.medications.length===0?<><div className="med-empty-benefits"><p><MedAsset file="b99b9.svg"/>Manage all your medications in one place.</p><p><MedAsset file="309d0.svg"/>Get reminder notifications.</p><p><MedAsset file="4219b.svg"/>Set a schedule and track your daily progress.</p></div><button className="primary-button" onClick={()=>beginMedication(flow,s)}>Add Medication</button></>:<><div>{s.medications.slice(0,3).map(m=><MedicationCard key={m.id} medication={m} compact/>)}</div><button className="med-view-more" onClick={()=>flow.push(medicationListScreen)}>View More <MedAsset file="809d4.svg" slot={16}/></button></>}</section>;}
const localTime=()=>new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());
function nextMedicationReminder(m:Medication,taken:Record<string,boolean>){for(let offset=0;offset<370;offset++){const d=dateAt(offset),key=new Intl.DateTimeFormat('sv-SE',{year:'numeric',month:'2-digit',day:'2-digit'}).format(d);if(!isScheduled(m,key))continue;const time=[...m.times].sort().find(t=>(offset>0||t>localTime())&&!taken[`${m.id}|${key}|${t}`]);if(time)return `${offset===0?'':offset===1?'Tomorrow ':dateLabel(key)+' '}${timeLabel(time)}`;}return 'Schedule ended';}
function MedicationDoseSheet({group,onOpenChange}:{group:{time:string;mode:'pending'|'taken'}|null;onOpenChange:(v:boolean)=>void}){const s=useMedications(),{notify}=useStore();const doses=group?scheduledDoses(s.medications,today).filter(d=>d.time===group.time):[];const title=group?.mode==='taken'?`Medications Taken On ${timeLabel(group.time)}`:`${group?timeLabel(group.time):''} Medications`;return <BottomSheet open={!!group} onOpenChange={onOpenChange} title={title} snap={0.68}><div className="med-dose-sheet"><button className="sheet-close icon-button" aria-label="Close medications" onClick={()=>onOpenChange(false)}><Icon name="close" size={24}/></button>{doses.map(d=><div className="med-dose-row" key={d.key}><div className="med-compact-name"><MedicationArt medication={d.medication} small dose/><strong>{d.medication.name}</strong><small>{medStrength(d.medication)}</small></div><div className="med-dose-action">{s.taken[d.key]?<span aria-label={d.medication.name+' taken'}><MedAsset file="6b0c1.svg" slot={24}/></span>:<button className="outline-button" aria-label={'Mark '+d.medication.name+' taken at '+timeLabel(d.time)} onClick={()=>{s.setTaken(p=>({...p,[d.key]:true}));notify('Medication marked as taken');}}><MedAsset file="cc07c.svg" slot={14}/>Taken</button>}</div><div className="med-compact-meta"><span><MedAsset file="383bd.svg" slot={14}/>{medAmount(d.medication)}</span>{d.medication.conditions.length>0&&<span><MedAsset file="3962b.svg" slot={14}/>{d.medication.conditions.join(', ')}</span>}</div>{d.medication.notes&&<p className="med-dose-note">Note : {d.medication.notes}</p>}{d.medication.reminders&&s.notifications?<p className="med-dose-reminder"><MedAsset file="c3036.svg"/>{s.taken[d.key]?'Next Reminder At '+nextMedicationReminder(d.medication,s.taken):'Reminder At '+timeLabel(d.time)}</p>:<button className="med-set-reminder" onClick={()=>{if(!s.notifications){notify('Enable notifications in Notification Settings first');return;}s.setMedications(current=>current.map(m=>m.id===d.medication.id?{...m,reminders:true}:m));notify('Medication reminder set as per schedule');}}>Set Reminder As Per Schedule</button>}</div>)}</div></BottomSheet>;}
function MedicationDashboard(){
 const s=useMedications();const[pendingOpen,setPendingOpen]=useState(false),[takenOpen,setTakenOpen]=useState(false),[group,setGroup]=useState<{time:string;mode:'pending'|'taken'}|null>(null);
 const [now,setNow]=useState(localTime);
 useEffect(()=>{const timer=window.setInterval(()=>setNow(localTime()),1000);return()=>window.clearInterval(timer);},[]);
 const doses=scheduledDoses(s.medications,today),progress=medicationProgress(s.medications,s.taken,today);const times=[...new Set(doses.map(d=>d.time))];const pendingTimes=orderPendingMedicationTimes(times.filter(t=>doses.some(d=>d.time===t&&!s.taken[d.key])),now);const upcoming=pendingTimes.find(t=>t>=now);const takenTimes=times.filter(t=>doses.some(d=>d.time===t&&s.taken[d.key]));
 return <><MobileScroll className="medication-scroll"><main className={'med-dashboard '+(!s.medications.length?'med-empty-dashboard':'')}><NotificationWarning/>{s.medications.length>0&&<><section className="med-progress"><div><p>Today’s Progress</p><h2>{progress.count} of {progress.total} Medicines taken</h2><div className="med-progress-counts"><span>Taken - {progress.count}</span><span>Pending - {progress.total-progress.count}</span></div></div><MedicationRing percent={progress.percent}/></section><section className="med-schedule-list"><h2>Medication Schedule</h2><button className="med-accordion" aria-expanded={pendingOpen} onClick={()=>setPendingOpen(v=>!v)}>Pending<MedAsset file="cff1c.svg" slot={20} className={pendingOpen?'rotate-180':''}/></button>{pendingOpen&&<div className="med-time-groups">{pendingTimes.length?pendingTimes.map(t=><button className="med-time-group" key={t} onClick={()=>setGroup({time:t,mode:'pending'})}><span><span className="med-clock-text">{timeLabel(t)}</span>{t===upcoming&&<small>Upcoming</small>}</span><span>{doses.filter(d=>d.time===t&&!s.taken[d.key]).length} {doses.filter(d=>d.time===t&&!s.taken[d.key]).length===1?'Medicine':'Medicines'}<MedAsset file="809d4.svg" slot={16}/></span></button>):<p className="med-schedule-empty">{progress.total?'All scheduled medications have been taken.':'No medications scheduled for today.'}</p>}</div>}<button className="med-accordion" aria-expanded={takenOpen} onClick={()=>setTakenOpen(v=>!v)}>Taken<MedAsset file="cff1c.svg" slot={20} className={takenOpen?'rotate-180':''}/></button>{takenOpen&&<div className="med-time-groups">{takenTimes.length?takenTimes.map(t=>{const ds=doses.filter(d=>d.time===t);return <div className="med-taken-group" key={t}><div><span>{timeLabel(t)}</span><button onClick={()=>setGroup({time:t,mode:'taken'})}>View <MedAsset file="809d4.svg" slot={16}/></button></div><div className="med-taken-dots"><span>{ds.filter(d=>s.taken[d.key]).length}/{ds.length} Taken</span><div>{ds.map(d=>s.taken[d.key]?<MedAsset key={d.key} file="2a8d8.svg" slot={18}/>:<CircleIcon key={d.key} width={18} height={18}/>)}</div></div></div>;}):<p className="med-schedule-empty">No medications taken yet today.</p>}</div>}</section></>}<div className="med-panel-wrap"><YourMedicationsPanel/></div></main></MobileScroll><MedicationDoseSheet group={group} onOpenChange={v=>{if(!v)setGroup(null);}}/></>;
}
function MedicationList(){const s=useMedications(),flow=useFlow();const[query,setQuery]=useState('');const matches=s.medications.filter(m=>[m.name,m.type,...m.conditions].join(' ').toLowerCase().includes(query.trim().toLowerCase()));return <MobileScroll className="medication-scroll"><main className="medication-full-list"><h1><button className="icon-button" aria-label="Back to medication dashboard" onClick={flow.pop}><MedAsset file="358f6.svg" slot={24}/></button>Your Medications</h1><div className="med-search"><MedAsset file="66aa3.svg" slot={24}/><KeyboardInput aria-label="Search medications" placeholder="Search by name, type and conditions" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button aria-label="Clear medication search" onClick={()=>setQuery('')}><Icon name="close" size={16}/></button>}</div><div className="med-list-results">{matches.map(m=><MedicationCard key={m.id} medication={m}/>)}{matches.length===0&&<p className="med-no-results">{query?'No medications found. Try a different name, type or condition.':'No medications added yet.'}</p>}</div></main></MobileScroll>;}
const medicationScreen:FlowScreen={id:'medication',headerHeight:84,header:()=> <MedicationHeader/>,render:()=> <MedicationDashboard/>};
const medicationListScreen:FlowScreen={id:'medication-list',headerHeight:84,header:()=> <MedicationHeader/>,footerHeight:60,footer:()=> <MedicationListFooter/>,render:()=> <MedicationList/>};
