const medicationEditorScreen:FlowScreen={id:'medication-editor',headerHeight:92,header:()=> <MedicationWizardHeader/>,footerHeight:60,footer:()=> <MedicationWizardFooter/>,render:()=> <MedicationWizard/>};
const medicationUpdateScheduleScreen:FlowScreen={id:'medication-update-schedule',headerHeight:52,header:()=> <MedicationWizardHeader scheduleOnly/>,footerHeight:60,footer:()=> <MedicationUpdateScheduleFooter/>,render:()=> <MedicationUpdateSchedule/>};
function Toast({text}:{text:string}){const{bottomInset}=useKeyboardInsets();return text?<div className="emp-toast" style={{bottom:bottomInset+16}} role="status"><CheckCircledIcon width={18} height={18}/>{text}</div>:null;}
export default function Prototype(){const[menuOpen,setMenuOpen]=useState(false);const[logs,setLogs]=useState(initialLogs),[reminder,setReminder]=useState<Reminder|null>(null),[draft,setDraft]=useState(freshReminder),[toast,setToast]=useState('');const toastTimer=useRef<number>(0);const notify=(text:string)=>{clearTimeout(toastTimer.current);setToast(text);toastTimer.current=window.setTimeout(()=>setToast(''),2600);};const reset=()=>{setLogs(initialLogs);setReminder(null);setDraft(freshReminder());};useEffect(()=>()=>clearTimeout(toastTimer.current),[]);return <MedicationProvider><StoreContext.Provider value={{menuOpen,setMenuOpen,logs,setLogs,reminder,setReminder,draft,setDraft,notify,reset}}><div className="empwr-app"><FlowStack initial={homeScreen}/><Toast text={toast}/></div></StoreContext.Provider></MedicationProvider>;}
